// Packs the binary's 32x32 pixel grid (`frame --pixels`) for each surface: a
// half-block `Raster` on the terminal, a run-merged `Svg` on desktop, vscode
// and mobile. Presentation only: the art itself is generated by the binary.
// Anything it cannot draw falls back to the ASCII sprite.
import type { ElementConstructor, RasterProps, RenderElement, SvgProps } from 'claude-code'

import { renderLines } from './lines'
import type { LineEls } from './lines'
import type { FrameJson } from '../types'

/** `pixels[y][x]`: `#rrggbb`, or null for transparent. */
export type PixelGrid = (string | null)[][]

/** The elements a sprite may need: `Raster` is the terminal's alone, `Svg` the remote surfaces'. */
export type SpriteEls = LineEls & {
  Raster?: ElementConstructor<RasterProps>
  Svg?: ElementConstructor<SvgProps>
}

const SIZE = 32
/** The terminal's own foreground / background (bit 24 alone). */
const DEFAULT_COLOR = 0x01000000
const UPPER_HALF = 0x2580
const LOWER_HALF = 0x2584
const SPACE = 0x20
/** Fewer columns than this to draw in: the ASCII sprite. */
const MIN_COLUMNS = 34
/** `Svg.source` is at most this many characters. */
const SVG_MAX = 131072
/** CSS pixels per sprite pixel on the remote surfaces. */
const SVG_SCALE = 6
/** The band portrait is the head-and-shoulders window of this many pixel rows. */
const PORTRAIT_ROWS = 20
const HEX = /^#[0-9a-fA-F]{6}$/

/** `0x00RRGGBB`, or the terminal default for null (and for anything that is not `#rrggbb`). */
export function hexToU32(hex: string | null): number {
  return hex !== null && HEX.test(hex) ? parseInt(hex.slice(1), 16) : DEFAULT_COLOR
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Standard padded RFC 4648 base64 (no `Buffer` / `btoa` assumed in the mod runtime). */
export function base64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i] ?? 0
    const b = bytes[i + 1] ?? 0
    const c = bytes[i + 2] ?? 0
    const n = (a << 16) | (b << 8) | c
    out += B64.charAt((n >> 18) & 63) + B64.charAt((n >> 12) & 63)
    out += i + 1 < bytes.length ? B64.charAt((n >> 6) & 63) : '='
    out += i + 2 < bytes.length ? B64.charAt(n & 63) : '='
  }
  return out
}

/**
 * Rows `[r0, r1)` as half-block cells, two pixel rows to one cell row. A
 * transparent half is never painted in the terminal's foreground: `▄` carries
 * a lone bottom pixel, `▀` a lone top one, and a space an empty cell.
 */
export function packRaster(px: PixelGrid, r0 = 0, r1 = px.length): { columns: number; rows: number; cells: string } {
  const columns = px[0]?.length ?? 0
  const rows = Math.max(0, Math.ceil((r1 - r0) / 2))
  const view = new DataView(new ArrayBuffer(columns * rows * 12))
  let at = 0
  for (let y = r0; y < r1; y += 2) {
    for (let x = 0; x < columns; x++) {
      const top = px[y]?.[x] ?? null
      const bottom = y + 1 < r1 ? (px[y + 1]?.[x] ?? null) : null
      let cell: [number, number, number]
      if (top !== null && bottom !== null) cell = [UPPER_HALF, hexToU32(top), hexToU32(bottom)]
      else if (top !== null) cell = [UPPER_HALF, hexToU32(top), DEFAULT_COLOR]
      else if (bottom !== null) cell = [LOWER_HALF, hexToU32(bottom), DEFAULT_COLOR]
      else cell = [SPACE, DEFAULT_COLOR, DEFAULT_COLOR]
      for (const word of cell) {
        view.setUint32(at, word, true)
        at += 4
      }
    }
  }
  return { columns, rows, cells: base64(new Uint8Array(view.buffer)) }
}

/**
 * The `height`-row window the band portrait shows: from the first row with a
 * painted pixel (0 if none), shifted up so it never passes the last row.
 */
export function cropRows(px: PixelGrid, height = PORTRAIT_ROWS): [number, number] {
  const total = px.length
  const first = px.findIndex(row => row.some(p => p !== null))
  const h = Math.min(height, total)
  const start = Math.max(0, Math.min(first < 0 ? 0 : first, total - h))
  return [start, start + h]
}

/** Rows `[r0, r1)` as one `<rect>` per horizontal run of equal colour (transparent skipped). */
export function svgSource(px: PixelGrid, r0 = 0, r1 = px.length): string {
  const width = px[0]?.length ?? 0
  const rects: string[] = []
  for (let y = r0; y < r1; y++) {
    const row = px[y] ?? []
    let x = 0
    while (x < width) {
      const color = row[x] ?? null
      if (color === null || !HEX.test(color)) {
        x++
        continue
      }
      let end = x + 1
      while (end < width && row[end] === color) end++
      rects.push(`<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${color}"/>`)
      x = end
    }
  }
  const head = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 ${r0} ${width} ${r1 - r0}" shape-rendering="crispEdges">`
  return `${head}${rects.join('')}</svg>`
}

/** A grid of the generator's shape (32 rows of 32); anything else is not drawn. */
function isGrid(px: PixelGrid | undefined): px is PixelGrid {
  return Array.isArray(px) && px.length === SIZE && px.every(row => Array.isArray(row) && row.length === SIZE)
}

const REMOTE: readonly string[] = ['desktop', 'vscode', 'mobile']

/** Whether `spriteElement` will draw pixel art for this frame, surface and width. */
export function usesPixels(els: SpriteEls, surface: string, frame: FrameJson, cols: number): boolean {
  if (!isGrid(frame.pixels) || !Number.isFinite(cols) || cols < MIN_COLUMNS) return false
  if (surface === 'terminal') return els.Raster !== undefined
  return REMOTE.includes(surface) && els.Svg !== undefined
}

/**
 * The kitten's picture: pixel art when the frame carries it and there are
 * `cols` columns to draw in, else the ASCII sprite. `portrait` is the band's
 * head-and-shoulders window, at most `rows` text rows tall on the terminal.
 */
export function spriteElement(
  els: SpriteEls,
  surface: string,
  frame: FrameJson,
  mode: 'full' | 'portrait',
  cols: number,
  rows = PORTRAIT_ROWS / 2,
): RenderElement {
  const px = frame.pixels
  if (!usesPixels(els, surface, frame, cols) || !isGrid(px)) return renderLines(els, frame.sprite)
  const [r0, r1] = mode === 'full' ? [0, SIZE] : cropRows(px, Math.min(PORTRAIT_ROWS, Math.max(2, Math.floor(rows) * 2)))
  if (surface === 'terminal' && els.Raster !== undefined) {
    const r = packRaster(px, r0, r1)
    return els.Raster({ key: mode === 'full' ? 'kitten-full' : 'kitten-portrait', columns: r.columns, rows: r.rows, cells: r.cells })
  }
  const source = svgSource(px, r0, r1)
  if (els.Svg === undefined || source.length > SVG_MAX) return renderLines(els, frame.sprite)
  return els.Svg({ source, alt: `${frame.name} the ${frame.breed}`, width: SIZE * SVG_SCALE, height: (r1 - r0) * SVG_SCALE })
}
